import { getAllProducts } from '@/lib/db';
import { cacheTag, revalidateTag } from 'next/cache';

async function getCachedProducts() {
  'use cache';
  cacheTag('products');
  return getAllProducts();
}

async function invalidateProducts() {
  'use server';
  revalidateTag('products');
}

async function ProductList() {
  const products = await getCachedProducts();
  return (
    <ul className="list-disc pl-5 my-4">
      {products.map((p) => (
        <li key={p.id} className="mb-2">
          <span className="font-semibold">{p.name}</span> - ${p.price}
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  return (
    <div className="p-8 font-sans">
      <h1 className="text-2xl font-bold mb-4">Product Listing</h1>
      <div className="mb-8">
        <h2 className="text-xl font-semibold mb-2">Cached Products</h2>
        <ProductList />
      </div>

      <div className="border-t pt-4">
        <h3 className="text-lg font-medium mb-2">Cache Controls</h3>
        <p className="mb-4 text-gray-600">
          Submitting the form below will invalidate the "products" cache tag, 
          causing the data to be re-fetched on the next request.
        </p>
        <form action={invalidateProducts}>
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Invalidate Products Cache
          </button>
        </form>
      </div>
    </div>
  );
}

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  experimental: {
    dynamicIO: true,
  },
};

export default nextConfig;

